<http://example.org/coat_suit_A> rdf:type ns2:CACAO_0000067 ;
    schema:description "Jacket in black wool, closing with plastic buttons in the centre front, with accents of black fabric with interwoven block pattern. Made of this are the small shawl collar, pocket turn-ups, sleeve cuffs and two flaps at neckline level (optical ends of a scarf or tie). The slanted side pockets are partially incorporated into a seam and emphasise the shape of the hips. No lining." ;
    ns3:P45_consists_of <http://example.org/black_wool_material>, <http://example.org/plastic_buttons_material>, <http://example.org/black_fabric_material> .

<http://example.org/skirt_B> rdf:type ns2:CACAO_0000066 ;
    schema:description "Black wool calf-length skirt with waistband, at the back at the bottom there are two pleats turned inwards. Closes with press-studs." ;
    ns3:P45_consists_of <http://example.org/black_wool_material>, <http://example.org/press_studs_material> .

<http://example.org/black_wool_material> rdf:type ns3:E57_Material ;
    ns3:P1_is_identified_by "black wool" .

<http://example.org/plastic_buttons_material> rdf:type ns3:E57_Material ;
    ns3:P1_is_identified_by "plastic buttons" .

